import { BrowserRouter as Router, Routes, Route } from "react-router-dom";

import Login from "./pages/login";
import Homepage from "./pages/homepage";
import Mybooking from "./pages/Mybooking";
import Review from "./pages/review";

import AdminLayout from "./pages/admin/admin_layout";
import AdminDashboard from "./pages/admin/admin_dash";

function AdminComingSoon({ title }) {
  return (
    <section>
      <h2>{title}</h2>
      <p>หน้านี้จะเชื่อมต่อกับฐานข้อมูลในขั้นตอนถัดไป</p>
    </section>
  );
}

function App() {
  return (
    <Router>
      <Routes>
        {/* User pages */}
        <Route path="/" element={<Login />} />
        <Route path="/homepage" element={<Homepage />} />
        <Route path="/homepage.html" element={<Homepage />} />
        <Route path="/mybooking" element={<Mybooking />} />
        <Route path="/Mybooking.html" element={<Mybooking />} />
        <Route path="/review" element={<Review />} />

        {/* Admin pages */}
        <Route path="/admin" element={<AdminLayout />}>
          <Route index element={<AdminDashboard />} />

          <Route
            path="rooms"
            element={<AdminComingSoon title="จัดการห้องประชุม" />}
          />

          <Route
            path="bookings"
            element={<AdminComingSoon title="จัดการการจอง" />}
          />

          <Route
            path="users"
            element={<AdminComingSoon title="จัดการผู้ใช้" />}
          />

          <Route
            path="reports"
            element={
              <AdminComingSoon title="ร้องเรียน แจ้งซ่อม และรีวิว" />
            }
          />
        </Route>
      </Routes>
    </Router>
  );
}

export default App;
